  ('Business Studies', 'Edexcel', 'alevel', '1.5', 'Entrepreneurs & Leaders', 'What are the rewards of starting a business?', 'Profit, independence, personal satisfaction and flexibility.', 4),
  ('Business Studies', 'Edexcel', 'alevel', '1.5', 'Entrepreneurs & Leaders', 'What is unlimited liability?', 'The owner is personally responsible for all the business''s debts.', 5),
  ('Business Studies', 'Edexcel', 'alevel', '1.5', 'Entrepreneurs & Leaders', 'What is limited liability?', 'Shareholders can only lose the amount they invested in the business.', 6),
  ('Business Studies', 'Edexcel', 'alevel', '1.5', 'Entrepreneurs & Leaders', 'What is a partnership?', 'A business owned by two to twenty people, usually with unlimited liability, sharing profits.', 7),
  ('Business Studies', 'Edexcel', 'alevel', '1.5', 'Entrepreneurs & Leaders', 'What is a private limited company?', 'A business owned by shareholders with limited liability; shares cannot be sold to the public.', 8),
