  ('Business Studies', 'Edexcel', 'alevel', '2.3', 'Managing Finance', 'What is the ideal current ratio?', 'Between 1.5:1 and 2:1.', 12),
  ('Business Studies', 'Edexcel', 'alevel', '2.3', 'Managing Finance', 'What is the acid test ratio formula?', '(Current assets − inventory) ÷ current liabilities.', 13),
