  ('Business Studies', 'Edexcel', 'alevel', '2.3', 'Managing Finance', 'What is a non-financial cause of business failure?', 'Poor management, weak marketing, or low-quality products.', 21),
  ('Business Studies', 'Edexcel', 'alevel', '2.3', 'Managing Finance', 'What is a receivables (debtors) problem?', 'Customers taking too long to pay, reducing cash available.', 22),
  ('Business Studies', 'Edexcel', 'alevel', '2.4', 'Resource Management', 'What is job production?', 'Making one-off products to individual customer requirements, e.g. a wedding dress.', 1),
