  ('Business Studies', 'Edexcel', 'alevel', '2.4', 'Resource Management', 'What is Total Quality Management?', 'An organisation-wide approach in which every employee is responsible for quality.', 22),
  ('Business Studies', 'Edexcel', 'alevel', '2.5', 'External Influences', 'What is inflation?', 'A sustained rise in the general price level.', 1),
